python3 -I - <<'PY'
import json, os, re, shlex
d = json.load(open(os.path.expanduser("~/.codex/hooks.json")))
paths = []
for ev, groups in d["hooks"].items():
    for g in groups:
        for h in g["hooks"]:
            for tok in shlex.split(h["command"]):
                if tok.startswith("/"):
                    paths.append((ev, tok))
bad = 0
for ev, p in paths:
    ok = os.path.exists(p)
    bad += not ok
    print(("ok  " if ok else "MISSING ") + ev + " " + p)
print("missing:", bad, "of", len(paths))
